function clInit(cols, rows, spacing, ox, oy){
  var pts=[]; 
  for(var y=0;y<rows;y++){ for(var x=0;x<cols;x++){ var px=ox+x*spacing, py=oy+y*spacing; pts.push({x:px,y:py,px:px,py:py,pin:(y===0 && x%2===0)}); } }
  var cons=[];
  for(var y=0;y<rows;y++){ for(var x=0;x<cols;x++){ var i=y*cols+x; if(x<cols-1) cons.push([i, y*cols+x+1]); if(y<rows-1) cons.push([i, (y+1)*cols+x]); } }
  return {cols:cols, rows:rows, spacing:spacing, pts:pts, cons:cons};
}
function clStep(s, gravity, drag, iterations){
  var pts=s.pts.map(function(p){ return {x:p.x,y:p.y,px:p.px,py:p.py,pin:p.pin}; });
  var i;
  for(i=0;i<pts.length;i++){ var p=pts[i]; if(p.pin) continue; var vx=(p.x-p.px)*drag, vy=(p.y-p.py)*drag; p.px=p.x; p.py=p.y; p.x+=vx; p.y+=vy+gravity; }
  for(var k=0;k<iterations;k++){
    for(var c=0;c<s.cons.length;c++){ var a=s.cons[c][0], b=s.cons[c][1]; var pa=pts[a], pb=pts[b]; var dx=pb.x-pa.x, dy=pb.y-pa.y; var d=Math.sqrt(dx*dx+dy*dy)||0.0001; var diff=(d-s.spacing)/d*0.5; var ox=dx*diff, oy=dy*diff; if(!pa.pin){ pa.x+=ox; pa.y+=oy; } if(!pb.pin){ pb.x-=ox; pb.y-=oy; } }
  }
  return {cols:s.cols, rows:s.rows, spacing:s.spacing, pts:pts, cons:s.cons};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { clInit:clInit, clStep:clStep };
}
if (typeof window !== 'undefined') {
  window.ClothForgePure = { clInit:clInit, clStep:clStep };
}
